let notes = flow.get('senkelNotes') || [];
if (!Number.isInteger(id) || id < 1) {
    msg.statusCode = 400;
    msg.payload = { error: 'id должен быть положительным целым' };
    return msg;
}
let found = null;
for (let i = 0; i < notes.length; i++) {
    if (notes[i].id === id) {
        found = notes[i];
    }
}
if (!found) {
    msg.statusCode = 404;
    msg.payload = { error: 'Заметка не найдена', id: id };
    return msg;
}
msg.statusCode = 200;
msg.payload = found;
return msg;

const body = msg.payload || {};
const title = typeof body.title === 'string' ? body.title.trim() : '';
const author = typeof body.author === 'string' ? body.author.trim() : '';
if (!title || !author) {
    msg.statusCode = 400;
    msg.payload = { error: 'Нужны непустые поля title и author' };
    return msg;
}
let notes = flow.get('senkelNotes');
if (!Array.isArray(notes)) {
    notes = [];
}
let seq = flow.get('senkelNotesSeq');
if (typeof seq !== 'number') {
    seq = 0;
}
seq = seq + 1;
const note = { id: seq, title: title, author: author };
notes.push(note);
flow.set('senkelNotes', notes);
flow.set('senkelNotesSeq', seq);
msg.statusCode = 201;
msg.payload = note;
return msg;

